--
-- Table structure for table `similar_tasks`
--

CREATE TABLE `similar_tasks` (
  `id` mediumint(7) UNSIGNED NOT NULL COMMENT 'Unique identifier',
  `task_id` smallint(5) UNSIGNED NOT NULL COMMENT 'Task ID',
  `similar_task_id` smallint(5) UNSIGNED NOT NULL COMMENT 'Similar Task ID',
  `similarity` decimal(5,2) UNSIGNED NOT NULL COMMENT 'Similarity percentage'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

